namespace NetScope {
 public static class Theme {
  public static bool IsDay { get; private set; }
  public static Color Back,Sidebar,Card,Border,Text,Muted,Accent,Blue,Amber,Red;
  static string preferencePath;
  static readonly Color[] Night={Color.FromArgb(14,20,31),Color.FromArgb(18,27,40),Color.FromArgb(24,35,50),Color.FromArgb(41,57,76),Color.FromArgb(228,237,246),Color.FromArgb(143,162,184),Color.FromArgb(68,218,188),Color.FromArgb(100,169,255),Color.FromArgb(249,194,104),Color.FromArgb(255,122,137)};
  static readonly Color[] Day={Color.FromArgb(247,249,248),Color.FromArgb(239,244,240),Color.White,Color.FromArgb(220,229,223),Color.FromArgb(24,39,57),Color.FromArgb(77,97,119),Color.FromArgb(35,132,81),Color.FromArgb(32,101,181),Color.FromArgb(153,91,5),Color.FromArgb(190,49,66)};
  static Theme(){SetDay(false);}
  public static void Load(string directory){preferencePath=System.IO.Path.Combine(directory,"ui-preferences.json");bool day=true;try{if(System.IO.File.Exists(preferencePath))day=System.IO.File.ReadAllText(preferencePath).Contains("day");}catch{}SetDay(day);}
  public static void Save(bool day){SetDay(day);if(!String.IsNullOrEmpty(preferencePath))System.IO.File.WriteAllText(preferencePath,day?"{\"theme\":\"day\"}":"{\"theme\":\"night\"}",new System.Text.UTF8Encoding(false));}
  public static void SetDay(bool day){IsDay=day;var p=day?Day:Night;Back=p[0];Sidebar=p[1];Card=p[2];Border=p[3];Text=p[4];Muted=p[5];Accent=p[6];Blue=p[7];Amber=p[8];Red=p[9];}
  public static Color Translate(Color color){for(int i=0;i<Night.Length;i++)if(color.ToArgb()==Night[i].ToArgb()||color.ToArgb()==Day[i].ToArgb())return(IsDay?Day:Night)[i];if(color.ToArgb()==Color.FromArgb(29,43,61).ToArgb()||color.ToArgb()==Color.FromArgb(222,231,240).ToArgb())return IsDay?Color.FromArgb(222,231,240):Color.FromArgb(29,43,61);if(color.ToArgb()==Color.FromArgb(21,32,46).ToArgb()||color.ToArgb()==Color.FromArgb(246,249,252).ToArgb())return IsDay?Color.FromArgb(246,249,252):Color.FromArgb(21,32,46);if(color.ToArgb()==Color.FromArgb(40,73,86).ToArgb()||color.ToArgb()==Color.FromArgb(207,233,232).ToArgb())return IsDay?Color.FromArgb(207,233,232):Color.FromArgb(40,73,86);if(color.ToArgb()==Color.FromArgb(32,62,70).ToArgb()||color.ToArgb()==Color.FromArgb(199,229,224).ToArgb())return IsDay?Color.FromArgb(199,229,224):Color.FromArgb(32,62,70);return color;}
  public static Font Font(float size,FontStyle style){return new Font("Microsoft YaHei UI",size,style,GraphicsUnit.Point);}
  public static string Rate(double value){if(double.IsNaN(value)||double.IsInfinity(value)||value<0)return "—"; if(value>=1048576)return (value/1048576).ToString("0.00")+" MiB/s";if(value>=1024)return (value/1024).ToString("0.0")+" KiB/s";return value.ToString("0")+" B/s";}
  public static string Delay(double? value){return value.HasValue?value.Value.ToString("0.0")+" ms":"—";}
  public static string LocalTime(DateTime value){return value.ToLocalTime().ToString("MM-dd HH:mm:ss");}
  public static GraphicsPath Round(RectangleF rect,float radius){var p=new GraphicsPath();float d=radius*2;if(rect.Width<=d||rect.Height<=d){p.AddRectangle(rect);return p;}p.AddArc(rect.X,rect.Y,d,d,180,90);p.AddArc(rect.Right-d,rect.Y,d,d,270,90);p.AddArc(rect.Right-d,rect.Bottom-d,d,d,0,90);p.AddArc(rect.X,rect.Bottom-d,d,d,90,90);p.CloseFigure();return p;}
 }
 public class SurfacePanel:Panel {
  public SurfacePanel(){DoubleBuffered=true;BackColor=Theme.Card;Padding=new Padding(18);}
  protected override void OnPaintBackground(PaintEventArgs e){e.Graphics.SmoothingMode=SmoothingMode.AntiAlias;e.Graphics.Clear(Parent==null?Theme.Back:Parent.BackColor);using(var path=Theme.Round(new RectangleF(.5f,.5f,Math.Max(1,Width-1),Math.Max(1,Height-1)),12)){using(var b=new SolidBrush(BackColor))e.Graphics.FillPath(b,path);using(var p=new Pen(Theme.Border))e.Graphics.DrawPath(p,path);}}
 }
 public class MetricCard:Control {
  public string Caption{get;set;} public string ValueText{get;set;} public string Detail{get;set;} public Color AccentColor{get;set;}
  public MetricCard(){DoubleBuffered=true;AccentColor=Theme.Accent;Caption="";ValueText="—";Detail="等待第一条样本";BackColor=Theme.Card;Margin=new Padding(0,0,12,0);Height=134;}
  protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);var g=e.Graphics;g.SmoothingMode=SmoothingMode.AntiAlias;g.Clear(Parent==null?Theme.Back:Parent.BackColor);using(var path=Theme.Round(new RectangleF(.5f,.5f,Width-1,Height-1),12)){using(var b=new SolidBrush(Theme.Card))g.FillPath(b,path);using(var p=new Pen(Theme.Border))g.DrawPath(p,path);}float scale=Math.Max(1,g.DpiY/96f);int pad=(int)(16*scale);int available=Math.Max(20,Width-pad*2);using(var captionFont=Theme.Font(9,FontStyle.Regular)){int captionHeight=TextRenderer.MeasureText(g,Caption,captionFont).Height+4;TextRenderer.DrawText(g,Caption,captionFont,new Rectangle(pad,pad,available,captionHeight),Theme.Muted,TextFormatFlags.EndEllipsis|TextFormatFlags.VerticalCenter|TextFormatFlags.NoPrefix);int valueTop=pad+captionHeight+2;int detailHeight;using(var detailFont=Theme.Font(8.5f,FontStyle.Regular)){detailHeight=TextRenderer.MeasureText(g,Detail,detailFont).Height+6;var detailRect=new Rectangle(pad,Math.Max(valueTop,Height-pad-detailHeight),available,detailHeight);TextRenderer.DrawText(g,Detail,detailFont,detailRect,Theme.Muted,TextFormatFlags.EndEllipsis|TextFormatFlags.VerticalCenter|TextFormatFlags.NoPrefix);}int valueHeight=Math.Max(20,Height-pad-detailHeight-valueTop-4);float valueSize=24;while(valueSize>12){using(var candidate=Theme.Font(valueSize,FontStyle.Bold)){var measured=TextRenderer.MeasureText(g,ValueText,candidate);if(measured.Width<=available&&measured.Height<=valueHeight)break;}valueSize-=1;}using(var valueFont=Theme.Font(valueSize,FontStyle.Bold))TextRenderer.DrawText(g,ValueText,valueFont,new Rectangle(pad,valueTop,available,valueHeight),AccentColor,TextFormatFlags.EndEllipsis|TextFormatFlags.VerticalCenter|TextFormatFlags.NoPrefix);}}

 }
 public class ChartPoint {public DateTime At;public double? Value;public string Segment;public ChartPoint(DateTime at,double? value,string segment=null){At=at;Value=value;Segment=segment;}}
 public class ChartSeries {public string Name;public Color Color;public List<ChartPoint> Points=new List<ChartPoint>();public ChartSeries(string name,Color color){Name=name;Color=color;}}
 public class TimeChart:Control {
  public List<ChartSeries> Series=new List<ChartSeries>();public bool ByteRate;public string Unit="ms";public string EmptyText="等待数据 · 完成一次检测后，这里会显示真实历史曲线";public DateTime RangeStart=DateTime.UtcNow.AddMinutes(-10),RangeEnd=DateTime.UtcNow;public TimeSpan GapLimit=TimeSpan.FromMinutes(3);int hoverX=-1;
  public TimeChart(){DoubleBuffered=true;BackColor=Theme.Card;ForeColor=Theme.Text;Font=Theme.Font(9,FontStyle.Regular);MinimumSize=new Size(250,160);AccessibleName="带时间和单位的网络历史曲线";MouseLeave+=delegate{hoverX=-1;Invalidate();};}
  protected override void OnMouseMove(MouseEventArgs e){base.OnMouseMove(e);hoverX=e.X;Invalidate();}
  public void UpdateData(List<ChartSeries> series,DateTime start,DateTime end,bool bytes){Series=series??new List<ChartSeries>();RangeStart=start;RangeEnd=end;ByteRate=bytes;Invalidate();}
  string Axis(double v){if(!ByteRate)return v.ToString(v>=10?"0":"0.0",CultureInfo.CurrentCulture)+" ms";if(v>=1048576)return (v/1048576).ToString("0.#")+" MiB/s";if(v>=1024)return(v/1024).ToString("0.#")+" KiB/s";return v.ToString("0")+" B/s";}
  static double NiceMax(double value){if(value<=0)return 1;var power=Math.Pow(10,Math.Floor(Math.Log10(value)));var fraction=value/power;return (fraction<=1?1:fraction<=2?2:fraction<=5?5:10)*power;}
  protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);var g=e.Graphics;g.SmoothingMode=SmoothingMode.AntiAlias;g.Clear(BackColor);if(Width<180||Height<100)return;var plot=new RectangleF(80,42,Width-100,Height-86);if(plot.Width<1||plot.Height<1)return;double seconds=Math.Max(1,(RangeEnd-RangeStart).TotalSeconds);var data=Series.SelectMany(s=>s.Points).Where(p=>p.Value.HasValue&&p.At>=RangeStart&&p.At<=RangeEnd&&!double.IsNaN(p.Value.Value)&&!double.IsInfinity(p.Value.Value)&&p.Value.Value>=0).ToList();double ymax=NiceMax(data.Count==0?(ByteRate?1024:100):Math.Max(1,data.Max(p=>p.Value.Value)*1.12));
   int legendX=10;foreach(var s in Series){using(var pen=new Pen(s.Color,3))g.DrawLine(pen,legendX,15,legendX+17,15);var sz=TextRenderer.MeasureText(s.Name,Font);TextRenderer.DrawText(g,s.Name,Font,new Point(legendX+24,5),Theme.Muted);legendX+=sz.Width+42;if(legendX>Width-130)break;}
   using(var gridPen=new Pen(Theme.Border)){for(int i=0;i<=4;i++){float y=plot.Bottom-plot.Height*i/4;g.DrawLine(gridPen,plot.Left,y,plot.Right,y);TextRenderer.DrawText(g,Axis(ymax*i/4),Font,new Rectangle(0,(int)y-10,72,20),Theme.Muted,TextFormatFlags.Right|TextFormatFlags.VerticalCenter);}for(int i=0;i<=4;i++){float x=plot.Left+plot.Width*i/4;DateTime at=RangeStart.AddSeconds(seconds*i/4).ToLocalTime();string format=seconds>=172800?"MM-dd":seconds>=86400?"MM-dd HH:mm":"HH:mm:ss";TextRenderer.DrawText(g,at.ToString(format),Font,new Rectangle(Math.Max(0,Math.Min(Width-90,(int)x-45)),(int)plot.Bottom+13,90,20),Theme.Muted,TextFormatFlags.HorizontalCenter);}}
   if(data.Count==0){using(var f=Theme.Font(10,FontStyle.Regular))TextRenderer.DrawText(g,EmptyText,f,Rectangle.Round(plot),Theme.Muted,TextFormatFlags.HorizontalCenter|TextFormatFlags.VerticalCenter|TextFormatFlags.WordBreak);return;}
   var state=g.Save();g.SetClip(plot);foreach(var s in Series){var pts=s.Points.Where(p=>p.At>=RangeStart&&p.At<=RangeEnd).OrderBy(p=>p.At).ToList();PointF? prev=null;DateTime prevTime=DateTime.MinValue;using(var pen=new Pen(s.Color,2.1f)){pen.LineJoin=LineJoin.Round;foreach(var p in pts){if(!p.Value.HasValue||double.IsNaN(p.Value.Value)||double.IsInfinity(p.Value.Value)||p.Value.Value<0){prev=null;continue;}var point=new PointF(plot.Left+(float)((p.At-RangeStart).TotalSeconds/seconds)*plot.Width,plot.Bottom-(float)(p.Value.Value/ymax)*plot.Height);if(prev.HasValue&&(p.At-prevTime)<=GapLimit){g.DrawLine(pen,prev.Value,point);}else{using(var brush=new SolidBrush(s.Color))g.FillEllipse(brush,point.X-2.5f,point.Y-2.5f,5,5);}prev=point;prevTime=p.At;}}}g.Restore(state);
   if(hoverX>=plot.Left&&hoverX<=plot.Right){DateTime when=RangeStart.AddSeconds((hoverX-plot.Left)/plot.Width*seconds);using(var pen=new Pen(Color.FromArgb(110,Theme.Muted))){pen.DashStyle=DashStyle.Dash;g.DrawLine(pen,hoverX,plot.Top,hoverX,plot.Bottom);}var text=new List<string>();text.Add("附近实测样本");foreach(var s in Series){var near=s.Points.Where(p=>p.Value.HasValue).OrderBy(p=>Math.Abs((p.At-when).TotalSeconds)).FirstOrDefault();if(near!=null&&Math.Abs((near.At-when).TotalSeconds)<=Math.Max(GapLimit.TotalSeconds,seconds/Width*10))text.Add(s.Name+"  "+(ByteRate?Theme.Rate(near.Value.Value):Theme.Delay(near.Value))+"  ["+near.At.ToLocalTime().ToString("MM-dd HH:mm:ss")+"]");}if(text.Count>1){string tooltip=String.Join("\n",text.ToArray());var size=TextRenderer.MeasureText(tooltip,Font);int bx=Math.Max(6,Math.Min(Width-size.Width-28,hoverX+13)),by=45;using(var p=Theme.Round(new RectangleF(bx,by,size.Width+18,size.Height+16),6)){using(var b=new SolidBrush(Color.FromArgb(240,Theme.Sidebar)))g.FillPath(b,p);using(var b=new Pen(Theme.Border))g.DrawPath(b,p);}TextRenderer.DrawText(g,tooltip,Font,new Point(bx+9,by+8),Theme.Text);}}
  }
 }
 public class DarkTabControl:TabControl {
  public DarkTabControl(){SetStyle(ControlStyles.UserPaint|ControlStyles.AllPaintingInWmPaint|ControlStyles.OptimizedDoubleBuffer|ControlStyles.ResizeRedraw,true);BackColor=Theme.Back;}
  protected override void OnSelectedIndexChanged(EventArgs e){base.OnSelectedIndexChanged(e);Invalidate();}
  protected override void OnPaint(PaintEventArgs e){e.Graphics.Clear(Theme.Back);for(int i=0;i<TabCount;i++){var rect=GetTabRect(i);bool selected=i==SelectedIndex;using(var b=new SolidBrush(selected?Theme.Translate(Color.FromArgb(32,62,70)):Theme.Sidebar))e.Graphics.FillRectangle(b,rect);using(var pen=new Pen(selected?Color.FromArgb(48,114,110):Theme.Border))e.Graphics.DrawRectangle(pen,rect.X,rect.Y,rect.Width-1,rect.Height-1);TextRenderer.DrawText(e.Graphics,TabPages[i].Text,Font,rect,selected?Theme.Accent:Theme.Muted,TextFormatFlags.HorizontalCenter|TextFormatFlags.VerticalCenter);}var body=DisplayRectangle;using(var pen=new Pen(Theme.Border))e.Graphics.DrawRectangle(pen,body.X-1,body.Y-1,body.Width+1,body.Height+1);}
 }
 public class CardFlowPanel:FlowLayoutPanel {public CardFlowPanel(){DoubleBuffered=true;BackColor=Theme.Back;FlowDirection=FlowDirection.LeftToRight;WrapContents=true;Padding=Padding.Empty;}}
 public class FriendlyIcon:Control {
  public string Kind="未知";public FriendlyIcon(){DoubleBuffered=true;Size=new Size(46,46);}
  protected override void OnPaint(PaintEventArgs e){var g=e.Graphics;g.SmoothingMode=SmoothingMode.AntiAlias;g.Clear(Parent==null?Theme.Card:Parent.BackColor);float s=Math.Min(Width,Height)/48f;var state=g.Save();g.ScaleTransform(s,s);using(var background=new SolidBrush(Theme.IsDay?Color.FromArgb(222,241,236):Color.FromArgb(29,66,69)))g.FillEllipse(background,0,0,46,46);using(var pen=new Pen(Theme.Accent,2)){if((Kind??"").Contains("电脑")||(Kind??"").Contains("程序")){g.DrawRectangle(pen,10,10,26,19);g.DrawLine(pen,23,29,23,35);g.DrawLine(pen,16,36,30,36);}else if((Kind??"").Contains("手机")){g.DrawRectangle(pen,15,7,17,31);g.DrawLine(pen,20,33,27,33);}else if((Kind??"").Contains("路由")){g.DrawRectangle(pen,10,22,27,14);g.DrawLine(pen,15,22,11,10);g.DrawLine(pen,32,22,36,10);g.DrawEllipse(pen,16,27,3,3);g.DrawEllipse(pen,25,27,3,3);}else{g.DrawEllipse(pen,10,10,26,26);using(var f=Theme.Font(15,FontStyle.Bold))TextRenderer.DrawText(g,"?",f,new Rectangle(10,7,27,32),Theme.Accent,TextFormatFlags.HorizontalCenter|TextFormatFlags.VerticalCenter);}}g.Restore(state);}
 }
 public class FriendlyTile:SurfacePanel {
  public readonly Label NameLabel=new Label(),StateLabel=new Label(),UsageLabel=new Label(),ReasonLabel=new Label();public readonly Button ActionButton=new RoundedButton{Borderless=true};public readonly FriendlyIcon Glyph=new FriendlyIcon();
  public FriendlyTile(){Height=240;Width=330;Padding=new Padding(15);var body=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=1,RowCount=4,BackColor=Theme.Card};body.RowStyles.Add(new RowStyle(SizeType.Absolute,62));body.RowStyles.Add(new RowStyle(SizeType.Absolute,38));body.RowStyles.Add(new RowStyle(SizeType.Percent,100));body.RowStyles.Add(new RowStyle(SizeType.Absolute,42));var heading=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=2,RowCount=1,Margin=Padding.Empty};heading.RowStyles.Add(new RowStyle(SizeType.Percent,100));heading.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,56));heading.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));heading.Controls.Add(Glyph,0,0);var texts=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=1,RowCount=2,Margin=Padding.Empty};texts.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));texts.RowStyles.Add(new RowStyle(SizeType.Absolute,32));texts.RowStyles.Add(new RowStyle(SizeType.Absolute,28));NameLabel.Font=Theme.Font(11,FontStyle.Bold);NameLabel.ForeColor=Theme.Text;StateLabel.Font=Theme.Font(9.5f,FontStyle.Regular);StateLabel.ForeColor=Theme.Muted;foreach(var label in new[]{NameLabel,StateLabel}){label.Dock=DockStyle.Fill;label.Margin=Padding.Empty;label.AutoEllipsis=true;label.TextAlign=ContentAlignment.MiddleLeft;}texts.Controls.Add(NameLabel,0,0);texts.Controls.Add(StateLabel,0,1);heading.Controls.Add(texts,1,0);body.Controls.Add(heading,0,0);UsageLabel.Dock=DockStyle.Fill;UsageLabel.Font=Theme.Font(10,FontStyle.Bold);UsageLabel.ForeColor=Theme.Accent;UsageLabel.TextAlign=ContentAlignment.MiddleLeft;UsageLabel.AutoEllipsis=true;body.Controls.Add(UsageLabel,0,1);ReasonLabel.Dock=DockStyle.Fill;ReasonLabel.Font=Theme.Font(10,FontStyle.Regular);ReasonLabel.ForeColor=Theme.Muted;ReasonLabel.AutoEllipsis=true;ReasonLabel.TextAlign=ContentAlignment.TopLeft;body.Controls.Add(ReasonLabel,0,2);ActionButton.Dock=DockStyle.Fill;ActionButton.FlatStyle=FlatStyle.Flat;ActionButton.FlatAppearance.BorderColor=Theme.Border;ActionButton.BackColor=Theme.Card;ActionButton.ForeColor=Theme.Accent;ActionButton.Font=Theme.Font(10,FontStyle.Regular);ActionButton.Cursor=Cursors.Hand;ActionButton.Margin=new Padding(0,2,0,0);body.Controls.Add(ActionButton,0,3);Controls.Add(body);}
 }
